        self.history.append(f"{num1} - {num2} = {result}")
        return result

    def multiply(self, num1, num2):

        result = num1 * num2
        self.history.append(f"{num1} * {num2} = {result}")
        return result

    def divide(self, num1, num2):

        if num2 == 0:
            raise ValueError("Cannot divide by zero")
        result = num1 / num2
        self.history.append(f"{num1} / {num2} = {result}")
        return result

    def display_history(self):

        print("\nCalculation History:")
