class Calculator:
    def __init__(self):
        self.history = []

    def add(self, num1, num2):

        result = num1 + num2
        print(f"{num1} + {num2} = {result}")
        self.history.append((num1, num2, result))
        return result

    def subtract(self, num1, num2):

        result = num1 - num2
        print(f"{num1} - {num2} = {result}")
        self.history.append((num1, num2, result))
        return result

    def multiply(self, num1, num2):

        result = num1 * num2
        print(f"{num1} * {num2} = {result}")
        self.history.append((num1, num2, result))
        return result

    def divide(self, num1, num2):

        if num2 == 0:
            raise ValueError("Cannot divide by zero")
        result = num1 / num2
        print(f"{num1} / {num2} = {result}")
        self.history.append((num1, num2, result))
        return result

    def display_history(self):

        if not self.history:
            print("No calculations yet")
        else:
            for i, (num1, num2, result) in enumerate(self.history):
                print(f"Calculation {i+1}: {num1} {self.get_operation_symbol(num2)} {num2} = {result}")


    def get_operation_symbol(self, num):
        if num == 0:
            return "+"
        elif num > 0:
            return "*"
        else:
            return "/"


def main():
    calculator = Calculator()
    while True:
        print("1. Addition")
        print("2. Subtraction")
        print("3. Multiplication")
        print("4. Division")
        print("5. Display History")
        print("6. Quit")

        choice = input("Choose an operation: ")

        if choice == "1":
            num1 = float(input("Enter first number: "))
            num2 = float(input("Enter second number: "))
